begin;
insert into auth.users(id) values ('11111111-1111-4111-8111-111111111111'),('22222222-2222-4222-8222-222222222222');
insert into public.profiles(uid,email) values ('11111111-1111-4111-8111-111111111111','a@test.invalid'),('22222222-2222-4222-8222-222222222222','b@test.invalid');
select test.ok((select count(*)=2 from subscriptions),'profile creation provisions typed free subscriptions');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select test.ok((select count(*)=1 from subscriptions),'subscription reads isolate owners');
select test.raises($$update subscriptions set plan='elite'$$,'42501','browser cannot grant paid plan');
select test.raises($$insert into usage_counters(user_id,month,feature) values(auth.uid(),date_trunc('month',now())::date,'statisticsAccess')$$,'42501','browser cannot forge counter');
select test.raises($$select reserve_usage(auth.uid(),'personalChatMessages')$$,'42501','browser cannot execute quota RPC');
select test.raises($$select read_monthly_usage(auth.uid())$$,'42501','browser cannot reclaim server reservations');
select test.raises($$select apply_billing_event('evt_forged',auth.uid(),'fake',now(),'{}')$$,'42501','browser cannot execute billing RPC');
select test.raises($$select complete_statistics_report(auth.uid(),gen_random_uuid(),'{}')$$,'42501','browser cannot publish paid report');
reset role;
set local role service_role;
select test.ok((reserve_usage('11111111-1111-4111-8111-111111111111','statisticsAccess')->>'allowed')::boolean=false,'free user statistics blocked in DB');
create temporary table reservations(value jsonb);
insert into reservations select reserve_usage('11111111-1111-4111-8111-111111111111','personalChatMessages') from generate_series(1,5);
select test.ok((select count(*)=5 from reservations where (value->>'allowed')::boolean),'free plan reserves exactly five messages');
select test.ok((reserve_usage('11111111-1111-4111-8111-111111111111','personalChatMessages')->>'allowed')::boolean=false,'inflight messages count against quota');
select finish_usage('11111111-1111-4111-8111-111111111111',(value->>'id')::uuid,false) from reservations limit 1;
select finish_usage('11111111-1111-4111-8111-111111111111',(value->>'id')::uuid,false) from reservations limit 1;
select test.ok((select used=0 and reserved=4 from usage_counters where feature='personalChatMessages'),'failed request released exactly once');
select finish_usage('11111111-1111-4111-8111-111111111111',(value->>'id')::uuid,true) from (select value from reservations offset 1 limit 1)r;
select finish_usage('11111111-1111-4111-8111-111111111111',(value->>'id')::uuid,true) from (select value from reservations offset 1 limit 1)r;
select test.ok((select used=1 and reserved=3 from usage_counters where feature='personalChatMessages'),'successful request charged exactly once');
select test.raises($$select finish_usage('22222222-2222-4222-8222-222222222222',(select id from usage_reservations limit 1),true)$$,'P0002','wrong reservation owner rejected');
update usage_reservations set expires_at=now()-interval '1 second' where status='reserved';
select read_monthly_usage('11111111-1111-4111-8111-111111111111');
select test.ok((select reserved=0 and used=1 from usage_counters where feature='personalChatMessages'),'expired holds reclaimed without removing committed usage');
insert into usage_counters(user_id,month,feature,used) values('11111111-1111-4111-8111-111111111111',(date_trunc('month',now())-interval '1 month')::date,'personalChatMessages',1000);
select test.ok((read_monthly_usage('11111111-1111-4111-8111-111111111111')->0->>'used')::integer=1,'past monthly usage excluded');
update subscriptions set plan='pro',status='active',current_period_end=now()+interval '1 month',stripe_customer_id='cus_a',stripe_subscription_id='sub_a' where user_id='11111111-1111-4111-8111-111111111111';
select test.ok((select subscription->>'plan'='pro' from profiles where uid='11111111-1111-4111-8111-111111111111'),'typed changes project to legacy billing JSON');
select test.ok((select used=1 from usage_counters where feature='personalChatMessages' and month=date_trunc('month',now())::date),'plan changes preserve current usage');
truncate reservations;
insert into reservations select reserve_usage('11111111-1111-4111-8111-111111111111','statisticsAccess');
select test.ok((reserve_usage('11111111-1111-4111-8111-111111111111','statisticsAccess')->>'busy')::boolean,'one concurrent statistics generation per owner');
select complete_statistics_report('11111111-1111-4111-8111-111111111111',(value->>'id')::uuid,'{"weekSummary":"synthetic"}') from reservations;
select test.ok((select used=1 and reserved=0 from usage_counters where feature='statisticsAccess'),'report persistence commits one access');
select test.ok((select report->>'weekSummary'='synthetic' from statistics_reports),'report saved atomically');
update subscription_plans set personal_chat_messages=1 where id='pro';
select test.ok((reserve_usage('11111111-1111-4111-8111-111111111111','personalChatMessages')->>'allowed')::boolean=false,'DB catalog changes immediately alter limits');
update subscriptions set current_period_end=now()-interval '1 second' where user_id='11111111-1111-4111-8111-111111111111';
select test.ok((reserve_usage('11111111-1111-4111-8111-111111111111','statisticsAccess')->>'allowed')::boolean=false,'expired paid period applies free limits without cron');
select apply_billing_event('evt_new','11111111-1111-4111-8111-111111111111','subscription.updated',now(),jsonb_build_object('plan','elite','status','active','stripeCustomerId','cus_a','stripeSubscriptionId','sub_a','currentPeriodEnd',now()+interval '1 month'));
select apply_billing_event('evt_new','11111111-1111-4111-8111-111111111111','subscription.updated',now(),'{}');
select apply_billing_event('evt_old','11111111-1111-4111-8111-111111111111','subscription.deleted',now()-interval '1 hour',jsonb_build_object('plan','free','status','canceled'));
select test.ok((select plan='elite' from subscriptions where user_id='11111111-1111-4111-8111-111111111111'),'duplicate and stale events cannot regress plan');
select test.ok((select count(*)=2 from billing_events),'billing event IDs unique');
select test.ok((select count(*)=1 from billing_email_outbox),'only one notification queued for accepted plan changes');
select test.ok((select count(*)=1 from claim_billing_emails()),'worker claims one notification');
select test.ok((select count(*)=0 from claim_billing_emails()),'concurrent worker cannot reclaim an active lease');
update billing_email_outbox set lease_until=now()-interval '1 second';
select test.ok((select attempts=2 from claim_billing_emails()),'expired worker leases support retry');
select test.raises($$update usage_counters set used=-1$$,'23514','negative consumption rejected');
select test.raises($$insert into subscriptions(user_id,plan) values('33333333-3333-4333-8333-333333333333','free')$$,'23503','billing owner FK enforced');
select test.ok(reserve_feedback('11111111-1111-4111-8111-111111111111','feedback-1'),'first feedback allowed');
select test.ok(reserve_feedback('11111111-1111-4111-8111-111111111111','feedback-1'),'feedback retry idempotent');
select reserve_feedback('11111111-1111-4111-8111-111111111111','feedback-'||n) from generate_series(2,5)n;
select test.ok(not reserve_feedback('11111111-1111-4111-8111-111111111111','feedback-6'),'sixth feedback blocked within one hour');
reset role;
set local role authenticated;
select test.ok((select count(*)=0 from usage_counters where user_id='22222222-2222-4222-8222-222222222222'),'foreign usage invisible');
select test.ok((select count(*)=1 from statistics_reports),'own report readable');
select test.raises('delete from billing_events','42501','browser cannot remove billing history');
reset role;
delete from auth.users where id='11111111-1111-4111-8111-111111111111';
select test.ok((select count(*)=1 from subscriptions),'account deletion cascades subscriptions');
select test.ok((select count(*)=0 from usage_counters),'account deletion cascades usage');
select test.ok((select count(*)=0 from usage_reservations),'account deletion cascades reservations');
select test.ok((select count(*)=0 from billing_events),'account deletion cascades billing events');
select test.ok((select count(*)=0 from statistics_reports),'account deletion cascades reports');
select test.ok((select count(*)=0 from feedback_requests),'account deletion cascades feedback rate records');
select test.ok((select count(*)=0 from billing_email_outbox),'account deletion cascades email jobs');
select count(*) as passed_billing_checks from test.results;
rollback;
